/* The BOOT0 strap (PH3, pad 60, pulled down on the board) shares its pad with
 * ONE signal.  The pad is sampled at reset: the signal rests low or analog, so
 * the strap reads 0 at every reset; while it is driven high the strap resistor
 * takes its current. */
#define GL_PINS_BOOT0_SHARED_WITH GL_PIN_CAM_R_PWDN

